matched_levels AS (
	SELECT
		"level"."id" AS id_level,
		adventure_data.*
	FROM adventure_data
	INNER JOIN "level" ON "level"."hash" = adventure_data.uid
	WHERE "level"."xx_hash" IS NULL
),
updated_levels AS (
	UPDATE "level"
	SET
		"xx_hash" = matched_levels.xx_hash,
		"adventure" = TRUE,
		"date_updated" = now()
	FROM matched_levels
	WHERE "level"."id" = matched_levels.id_level
	RETURNING matched_levels.*
),
inserted_level_items AS (
	INSERT INTO "level_item" (
	"id_level",
	"workshop_id",
	"author_id",
	"name",
	"image_url",
	"file_author",
	"file_uid",
	"validation_time_author",
	"validation_time_gold",
	"validation_time_silver",
	"validation_time_bronze",
	"deleted",
	"created_at",
	"updated_at",
	"date_created",
	"date_updated"
)
	SELECT
		updated_levels.id_level,
		-1::bigint,
		76561198041027402::bigint,
		updated_levels.name,
		updated_levels.image_url,
		'Yannic',
		updated_levels.uid,
		updated_levels.validation_time_author,
		updated_levels.validation_time_gold,
		updated_levels.validation_time_silver,
		updated_levels.validation_time_bronze,
		FALSE,
		now(),
		now(),
		now(),
		now()
	FROM updated_levels
	WHERE NOT EXISTS (
		SELECT 1
		FROM "level_item"
		WHERE "level_item"."id_level" = updated_levels.id_level
			AND "level_item"."file_uid" = updated_levels.uid
	)
	RETURNING 1
)
INSERT INTO "level_metadata" (
	"id_level",
	"amount_checkpoints",
	"amount_finishes",
	"amount_blocks",
	"type_ground",
	"type_skybox",
	"format",
	"blocks",
	"date_created",
	"date_updated"
)
SELECT
	updated_levels.id_level,
	updated_levels.amount_checkpoints,
	updated_levels.amount_finishes,
	updated_levels.amount_blocks,
	updated_levels.type_ground,
	updated_levels.type_skybox,
	updated_levels.format,
	updated_levels.blocks,
	now(),
	now()
FROM updated_levels
WHERE NOT EXISTS (
	SELECT 1
	FROM "level_metadata"
	WHERE "level_metadata"."id_level" = updated_levels.id_level
);
